/* ---- PlayEveryWare.EpicOnlineServices.EOSManager.EOSSingleton ----
 *
 * Init(IEOSCoroutineOwner coroutineOwner, string configFileName).
 *
 * The exact frame from the managed exception that stopped the boot:
 *
 *     Unity: Exception: Epic Online Services didn't init correctly: NotConfigured
 *       at PlayEveryWare.EpicOnlineServices.EOSManager+EOSSingleton.Init
 *          (IEOSCoroutineOwner coroutineOwner, String configFileName)
 *
 * Instance method, returns void, so a hook that returns immediately is a
 * complete replacement -- `this` and both arguments are simply unread. */
#define BMM_RVA_EOSManager_Init   0x2002544u
#define BMM_G3_EOSManager_Init    { 0xd10143ffu, 0xf90013feu, 0xa90357f6u }

