/* ---- AppLovin MAX (MaxSdkAndroid) ----
 *
 * The game polls MaxSdk.IsInitialized() and logs "MaxAds: Not initialized yet"
 * until it turns true. It never does: InitializeSdk() reaches the real SDK
 * through an AndroidJavaClass that does not exist here, and the SDK's
 * OnSdkInitializedEvent callback is delivered by Java code we do not have.
 * Same shape as the Firebase Future -- a callback that can never arrive.
 *
 * Class is MaxSdkAndroid (extends MaxSdkBase); the platform-neutral MaxSdk
 * forwards to it. Hooking the Android implementation covers every caller. */
#define BMM_RVA_MaxSdkAndroid_IsInitialized  0x3500198u
#define BMM_G3_MaxSdkAndroid_IsInitialized   { 0xf81e0ffeu, 0xa9014ff4u, 0x9000b474u }
#define BMM_RVA_MaxSdkAndroid_InitializeSdk  0x34fff4cu
#define BMM_G3_MaxSdkAndroid_InitializeSdk   { 0xf81d0ffeu, 0xa90157f6u, 0xa9024ff4u }

int bm_maxads_install(so_module *il2cpp);

/* ---- Bootstrap.LoadingSteps.EpicLoginCheckLoadingStep ----
 *
 * Its LoadStepInternal is a UniTask that does
 * `await UniTask.WaitUntil(() => persistentCheckComplete)`, and the flag is set
 * only by the EOS login callback:
 *
 *     b__3_2()      ldrb w0, [x0, #0x28]   ; return persistentCheckComplete
 *                   ret
 *     b__3_1(bool)  mov  w8, #1
 *                   strb w8, [x0, #0x28]   ; set by the login callback
 *                   ret
 *
 * EOSManager.Init is neutralised (there is no EOS here), so b__3_1 never runs
 * and the step waits forever -- silently, with no polling and no exception,
 * which is why nothing showed in the log.
 *
 * PATCHED IN PLACE, NOT HOOKED. The predicate is EIGHT BYTES; hook_arm64 writes
 * sixteen and would overwrite the start of the following function. Replacing
 * the single `ldrb` with `mov w0, #1` leaves the existing `ret` to do its job.
 *
 * The guard covers the whole function (both instructions) rather than the usual
 * three words -- a third word here would reach into the NEXT function, which
 * can move independently and would make this fail for the wrong reason.
 */
#define BMM_RVA_EpicLoginCheck_pred  0x1fa37b8u
#define BMM_G2_EpicLoginCheck_pred   { 0x3940a000u, 0xd65f03c0u }  /* ldrb w0,[x0,#0x28] ; ret */
#define BMM_PATCH_EpicLoginCheck_pred 0x52800020u                  /* mov w0, #1            */

/* In-place word patch inside libil2cpp, guarded. Returns 1 on success. */
int bm_managed_patch(so_module *il2cpp, const char *what, uint32_t rva,
                     const uint32_t *guard, int nguard, uint32_t word);

/* Verify all guard words, then write all replacement words. Use this to replace
 * a function body -- a partial rewrite is worse than none. */
int bm_managed_patch_n(so_module *il2cpp, const char *what, uint32_t rva,
                       const uint32_t *guard, const uint32_t *words, int n);

int bm_epiclogin_install(so_module *il2cpp);

/* ---- Bootstrap.GameLoadingStep.LoadStep ----
 *
 * Detoured (not replaced) to log which step is ENTERED -- the bootstrap only
 * logs completions, so a step that starts and never returns is invisible.
 * See bm_steptrace.c.
 *
 * FOUR guard words, because the detour re-emits exactly these four instructions
 * in our own .text before branching to LoadStep+0x10. They are all
 * position-independent, which is what makes a trampoline-free detour safe here;
 * if any of them changes, the replay would be wrong and the trace must not
 * install. */
#define BMM_RVA_GameLoadingStep_LoadStep  0x1f9edf8u
#define BMM_G4_GameLoadingStep_LoadStep   { 0xd101c3ffu, 0xf90023feu, \
                                            0xa90557f6u, 0xa9064ff4u }

/* RemoteConfigService.Bind -- traced entry AND exit via a callable trampoline.
 * Step #6 (RemoteConfigLoadingStep) calls it and never completes; if Bind
 * throws, ENTER appears without EXIT. */
#define BMM_RVA_RemoteConfigService_Bind  0x20baffcu
#define BMM_G4_RemoteConfigService_Bind   { 0xf81e0ffeu, 0xa9014ff4u, \
                                            0xaa0103f3u, 0xaa0003f4u }

/* ---- EpicLoginCheckLoadingStep.LoadStepInternal ----
 *
 * The step tracer identified this as the step that starts and never finishes
 * (ENTER #6 with no completion). Its state machine has TWO UniTask.WaitUntil
 * calls with EpicSDKManager.CheckPersistentLogin between them -- sec.33 forced
 * only one predicate true, which is why that patch changed nothing.
 *
 * Rather than chase the second predicate, skip the step. There is no EOS on
 * this platform (EOSManager.Init is neutralised, sec.23), so "check for a
 * persistent Epic login" has no meaningful answer and nothing downstream reads
 * a result from it.
 *
 * RETURNING A COMPLETED UniTask IS THREE INSTRUCTIONS. UniTask is
 * { IUniTaskSource source; short token; } and `default(UniTask)` -- a null
 * source -- is precisely UniTask.CompletedTask: GetAwaiter().IsCompleted
 * short-circuits to true when source is null. A 16-byte struct returns in
 * x0:x1, so zeroing both and returning IS a completed task. No allocation, no
 * runtime support, nothing to get wrong.
 *
 * The method is 136 bytes (next symbol is .ctor at 0x1FA37A4), so a 12-byte
 * patch is comfortably inside it. */
#define BMM_RVA_EpicLoginCheck_LoadStepInternal 0x1fa371cu
#define BMM_G3_EpicLoginCheck_LoadStepInternal  { 0xd10143ffu, 0xa90357feu, 0xa9044ff4u }

